create or replace function public.nodara_number_warehouse_receipt() returns trigger language plpgsql security definer set search_path=public as $$ begin if nullif(btrim(new.receipt_number),'') is null then new.receipt_number:=public.next_document_number(new.organization_id,'WAREHOUSE_RECEIPT'); end if; return new; end $$;
drop trigger if exists trg_00_number_warehouse_receipt on public.warehouse_receipts; create trigger trg_00_number_warehouse_receipt before insert on public.warehouse_receipts for each row execute function public.nodara_number_warehouse_receipt();
create or replace function public.nodara_number_cargo_release() returns trigger language plpgsql security definer set search_path=public as $$ begin if nullif(btrim(new.release_number),'') is null then new.release_number:=public.next_document_number(new.organization_id,'CARGO_RELEASE'); end if; return new; end $$;
drop trigger if exists trg_00_number_cargo_release on public.cargo_releases; create trigger trg_00_number_cargo_release before insert on public.cargo_releases for each row execute function public.nodara_number_cargo_release();

create or replace function public.nodara_guard_shipment_write() returns trigger language plpgsql security definer set search_path=public as $$ begin if not public.nodara_is_org_member(new.organization_id) then raise exception 'Workspace access denied'; end if; perform public.nodara_assert_entity_in_org(new.organization_id,new.customer_id,'Customer'); perform public.nodara_assert_entity_in_org(new.organization_id,new.shipper_id,'Shipper'); perform public.nodara_assert_entity_in_org(new.organization_id,new.consignee_id,'Consignee'); perform public.nodara_assert_entity_in_org(new.organization_id,new.carrier_id,'Carrier'); if coalesce(new.pieces,0)<0 or coalesce(new.weight,0)<0 or coalesce(new.volume_cbm,0)<0 then raise exception 'Shipment quantities and measurements cannot be negative'; end if; if tg_op='INSERT' and nullif(btrim(new.shipment_number),'') is null then new.shipment_number:=public.next_document_number(new.organization_id,'SHIPMENT_'||upper(new.mode)); end if; new.updated_at:=now(); return new; end $$;
create or replace function public.nodara_guard_transport_order_write() returns trigger language plpgsql security definer set search_path=public as $$ begin if not public.nodara_is_org_member(new.organization_id) then raise exception 'Workspace access denied'; end if; perform public.nodara_assert_entity_in_org(new.organization_id,new.customer_id,'Customer'); perform public.nodara_assert_entity_in_org(new.organization_id,new.carrier_id,'Carrier'); perform public.nodara_assert_entity_in_org(new.organization_id,new.pickup_entity_id,'Pickup entity'); perform public.nodara_assert_entity_in_org(new.organization_id,new.delivery_entity_id,'Delivery entity'); if coalesce(new.pieces,0)<0 or coalesce(new.weight,0)<0 or coalesce(new.sell_amount,0)<0 or coalesce(new.buy_amount,0)<0 then raise exception 'Transport quantities and amounts cannot be negative'; end if; if tg_op='INSERT' and nullif(btrim(new.order_number),'') is null then new.order_number:=public.next_document_number(new.organization_id,upper(new.order_type)); end if; new.updated_at:=now(); return new; end $$;

create or replace function public.nodara_transaction_org(p_transaction_type text,p_transaction_id uuid) returns uuid language plpgsql stable security definer set search_path=public as $$ declare o uuid; begin case upper(p_transaction_type) when 'SHIPMENT' then select organization_id into o from public.shipments where id=p_transaction_id; when 'TRANSPORT_ORDER' then select organization_id into o from public.transport_orders where id=p_transaction_id; when 'WAREHOUSE_RECEIPT' then select organization_id into o from public.warehouse_receipts where id=p_transaction_id; when 'CARGO_RELEASE' then select organization_id into o from public.cargo_releases where id=p_transaction_id; else raise exception 'Unsupported transaction type %',p_transaction_type; end case; if o is null then raise exception 'Transaction not found'; end if; return o; end $$;
create or replace function public.assign_cargo_atomic(p_transaction_type text,p_transaction_id uuid,p_cargo_ids uuid[]) returns integer language plpgsql security definer set search_path=public as $$ declare o uuid; cid uuid; seq integer:=0; c_org uuid; cnt integer:=0; begin o:=public.nodara_transaction_org(p_transaction_type,p_transaction_id); if not public.nodara_is_org_member(o) then raise exception 'Workspace access denied'; end if; if coalesce(array_length(p_cargo_ids,1),0)=0 then return 0; end if; foreach cid in array p_cargo_ids loop select organization_id into c_org from public.cargo_objects where id=cid for update; if c_org is null then raise exception 'Cargo % not found',cid; end if; if c_org<>o then raise exception 'Cargo and transaction must belong to the same workspace'; end if; insert into public.cargo_assignments(organization_id,cargo_object_id,transaction_type,transaction_id,assignment_role,sequence_no,status,updated_at) values(o,cid,upper(p_transaction_type),p_transaction_id,'CARGO',seq,'ASSIGNED',now()) on conflict(cargo_object_id,transaction_type,transaction_id,assignment_role) do update set status='ASSIGNED',sequence_no=excluded.sequence_no,updated_at=now(); insert into public.cargo_events(organization_id,cargo_object_id,event_type,transaction_type,transaction_id,performed_by,metadata) values(o,cid,'ASSIGNED',upper(p_transaction_type),p_transaction_id,auth.uid(),jsonb_build_object('atomic',true)); seq:=seq+1; cnt:=cnt+1; end loop; return cnt; end $$;
create or replace function public.nodara_create_transaction_cargo_node(p_org uuid,p_transaction_type text,p_transaction_id uuid,p_node jsonb,p_parent uuid default null) returns uuid language plpgsql security definer set search_path=public as $$ declare id_out uuid; q numeric; defaults jsonb; begin q:=coalesce(nullif(p_node->>'quantity','')::numeric,1); if q<=0 then raise exception 'Cargo quantity must be greater than zero'; end if; defaults:=coalesce(public.resolve_unit_defaults(p_org,upper(p_transaction_type)),'{}'::jsonb); insert into public.cargo_objects(organization_id,source_type,source_id,parent_cargo_id,package_type,quantity,uom,description,gross_weight,weight_unit,length,width,height,dimension_unit,status,metadata) values(p_org,'TRANSACTION',p_transaction_id,p_parent,coalesce(nullif(p_node->>'package_type',''),'CARTON'),q,coalesce(nullif(p_node->>'uom',''),defaults->>'quantity_uom'),nullif(p_node->>'description',''),nullif(p_node->>'gross_weight','')::numeric,coalesce(nullif(p_node->>'weight_unit',''),defaults->>'weight_unit'),nullif(p_node->>'length','')::numeric,nullif(p_node->>'width','')::numeric,nullif(p_node->>'height','')::numeric,coalesce(nullif(p_node->>'dimension_unit',''),defaults->>'dimension_unit'),'ASSIGNED',jsonb_build_object('transaction_local',true,'transaction_type',upper(p_transaction_type),'part_number',nullif(p_node->>'part_number',''),'sku',nullif(p_node->>'sku',''),'barcode',nullif(p_node->>'barcode',''))) returning id into id_out; if jsonb_typeof(p_node->'children')='array' then perform public.nodara_create_transaction_cargo_node(p_org,p_transaction_type,p_transaction_id,ch,id_out) from jsonb_array_elements(p_node->'children') ch; end if; return id_out; end $$;
create or replace function public.create_transaction_cargo_tree_atomic(p_transaction_type text,p_transaction_id uuid,p_tree jsonb) returns uuid language plpgsql security definer set search_path=public as $$ declare o uuid; root_id uuid; begin o:=public.nodara_transaction_org(p_transaction_type,p_transaction_id); if not public.nodara_is_org_member(o) then raise exception 'Workspace access denied'; end if; if p_tree is null or jsonb_typeof(p_tree)<>'object' then raise exception 'Cargo tree payload is required'; end if; root_id:=public.nodara_create_transaction_cargo_node(o,upper(p_transaction_type),p_transaction_id,p_tree,null); perform public.assign_cargo_atomic(upper(p_transaction_type),p_transaction_id,array[root_id]); return root_id; end $$;
create or replace function public.remove_cargo_assignment_atomic(p_assignment_id uuid) returns boolean language plpgsql security definer set search_path=public as $$ declare a public.cargo_assignments%rowtype; begin select * into a from public.cargo_assignments where id=p_assignment_id for update; if a.id is null then raise exception 'Cargo assignment not found'; end if; if not public.nodara_is_org_member(a.organization_id) then raise exception 'Workspace access denied'; end if; update public.cargo_assignments set status='REMOVED',updated_at=now() where id=a.id; insert into public.cargo_events(organization_id,cargo_object_id,event_type,transaction_type,transaction_id,performed_by,metadata) values(a.organization_id,a.cargo_object_id,'UNASSIGNED',a.transaction_type,a.transaction_id,auth.uid(),jsonb_build_object('atomic',true)); return true; end $$;
create or replace function public.delete_transaction_cargo_subtree_atomic(p_cargo_object_id uuid) returns integer language plpgsql security definer set search_path=public as $$ declare c public.cargo_objects%rowtype; n integer; begin select * into c from public.cargo_objects where id=p_cargo_object_id for update; if c.id is null then raise exception 'Cargo not found'; end if; if not public.nodara_is_org_member(c.organization_id) then raise exception 'Workspace access denied'; end if; if c.source_type<>'TRANSACTION' or coalesce((c.metadata->>'transaction_local')::boolean,false) is not true then raise exception 'Only transaction-local cargo may be deleted here'; end if; with recursive tree as (select id from public.cargo_objects where id=c.id union all select x.id from public.cargo_objects x join tree t on x.parent_cargo_id=t.id) delete from public.cargo_objects where id in(select id from tree); get diagnostics n=row_count; return n; end $$;
grant execute on function public.nodara_transaction_org(text,uuid),public.assign_cargo_atomic(text,uuid,uuid[]),public.create_transaction_cargo_tree_atomic(text,uuid,jsonb),public.remove_cargo_assignment_atomic(uuid),public.delete_transaction_cargo_subtree_atomic(uuid) to authenticated;
